def cari_biner(a, target):
    kiri, kanan = 0, len(a) - 1
    while kiri <= kanan:
        tengah = (kiri + kanan) // 2
        if a[tengah] == target:
            return tengah
        elif a[tengah] < target:
            kiri = tengah + 1
        else:
            kanan = tengah - 1
    return -1

