class Rak:
    def __init__(self, kapasitas):
        self._slot = [None] * kapasitas
        self._size = 0

    def taruh(self, sepatu):
        if self._size == len(self._slot):
            return False
        self._slot[self._size] = sepatu
        self._size += 1
        return True

    def isi(self):
        return self._slot[:self._size]

